CREATE DEFINER=`root`@`localhost` FUNCTION `fn_generate_birthdate_by_age`(p_min_age INT, p_max_age INT) RETURNS date
    DETERMINISTIC
BEGIN
    DECLARE v_random_years INT;
    DECLARE v_random_days INT;
    
    -- Calcular diferencia de años en el rango
    SET v_random_years = p_min_age + FLOOR(RAND() * (p_max_age - p_min_age + 1));
    SET v_random_days = FLOOR(RAND() * 365);
    
    RETURN DATE_SUB(DATE_SUB(CURDATE(), INTERVAL v_random_years YEAR), INTERVAL v_random_days DAY);
END ;;
DELIMITER ;
