DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_new_user`(
    -- Datos para tb_users
    IN p_email VARCHAR(80),
    IN p_nick VARCHAR(100),
    IN p_password VARCHAR(255),
    
    -- Datos para tb_people
    IN p_courtesy_title VARCHAR(50),
    IN p_given_names VARCHAR(150),
    IN p_family_names VARCHAR(150),
    IN p_birth_date DATE,
    IN p_gender_ID TINYINT UNSIGNED,
    IN p_country_code CHAR(2),
    IN p_phone VARCHAR(25),
    
    -- Parámetros de salida
    OUT p_user_ID INT,
    OUT p_person_ID BIGINT UNSIGNED
)
BEGIN
    -- Manejador de excepciones: deshace cambios si ocurre algún error
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    -- Inicio de la transacción
    START TRANSACTION;

    -- 1. Insertar en tb_users aplicando MD5 a la contraseña
        `email`, 
        `nick`, 
        `password`
    ) VALUES (
        p_email, 
        p_nick, 
        MD5(p_password)
    );

    -- Obtener el ID del usuario recién creado
    SET p_user_ID = LAST_INSERT_ID();

    -- 2. Insertar en tb_people vinculando el user_ID generado
        `user_ID`, 
        `courtesy_title`, 
        `given_names`, 
        `family_names`, 
        `birth_date`, 
        `gender_ID`, 
        `country_code`, 
        `phone`
    ) VALUES (
        p_user_ID, 
        p_courtesy_title, 
        p_given_names, 
        p_family_names, 
        p_birth_date, 
        p_gender_ID, 
        p_country_code, 
        p_phone
    );

    -- Obtener el ID de la persona recién creada
    SET p_person_ID = LAST_INSERT_ID();

    -- Confirmar los cambios
    COMMIT;
END ;;
DELIMITER ;
